import math

def interp(pts,x):
    pts=sorted(pts)
    for a,b in zip(pts,pts[1:]):
        if a[0]<=x<=b[0] and b[0]-a[0]>0.001:
            return a[1]+(b[1]-a[1])*(x-a[0])/(b[0]-a[0])
    return None

def control(obs):
    m=obs['local_map']
    left=m.get('left_rail',[])
    right=m.get('right_rail',[])
    h=obs['hitch_deg']
    targets=[]
    for x in [3.0,4.0,5.0,6.0]:
        a=interp(left,x); b=interp(right,x)
        if a is not None and b is not None:
            targets.append((x,(a+b)/2))
    if not targets:
        return (h*2,0,180)
    x,y=targets[-1]
    k=2*y/(x*x+y*y)
    desired=max(-34,min(34,math.degrees(math.atan(4.9*k))))
    equilibrium=math.degrees(math.atan(2.5*math.sin(math.radians(h))/(3.6+1.3*math.cos(math.radians(h)))))
    steer=max(-45,min(45,equilibrium+1.8*(h-desired)))
    speed=-0.75 if abs(h)>25 else -1.0
    return (steer,speed,180)

