import math
def clamp(x,a,b): return max(a,min(b,x))
def dist(p,rail):
    best=100.0
    for a,b in zip(rail,rail[1:]):
        dx=b[0]-a[0]; dy=b[1]-a[1]
        f=clamp(((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy+1e-9),0,1)
        best=min(best,math.hypot(p[0]-a[0]-f*dx,p[1]-a[1]-f*dy))
    return best
def control(obs):
    rails=obs['local_map']; left=rails.get('left_rail',[]); right=rails.get('right_rail',[])
    h=obs['hitch_deg']
    if len(left)<2 or len(right)<2:
        return (clamp(3*h,-45,45),-0.22,180)
    radius=1.6
    best=None
    for i in range(-70,71):
        a=math.radians(i); p=(radius*math.cos(a),radius*math.sin(a))
        dl=dist(p,left); dr=dist(p,right)
        score=(dl-dr)**2+0.012*a*a
        if best is None or score<best[0]: best=(score,p,dl,dr)
    p=best[1]
    curvature=2*p[1]/(radius*radius)
    target=clamp(math.degrees(math.atan(0.85*curvature)),-27,27)
    steer=clamp(1.09*target+3.0*(h-target),-45,45)
    speed=-0.43 if abs(h)<23 else -0.27
    if abs(h)>43:
        wake('Large hitch angle; checking recovery')
        return (clamp(2*h,-45,45),0,180)
    return (steer,speed,180)

