import math
def clip(x,a,b): return max(a,min(b,x))
def interp(points,u):
    p=sorted(points)
    for a,b in zip(p,p[1:]):
        if a[0]<=u<=b[0]:
            f=(u-a[0])/max(0.001,b[0]-a[0]); return a[1]+f*(b[1]-a[1])
    return None
def control(obs):
    m=obs['local_map']; left=m.get('left_rail',[]); right=m.get('right_rail',[])
    targets=[]
    for u in [7,9,11,13]:
        l=interp(left,u); r=interp(right,u)
        if l is not None and r is not None: targets.append((u,(l+r)/2))
    h=obs['hitch_deg']
    if not targets: return (clip(h*1.8,-42,42),-0.45,180)
    u,v=targets[min(2,len(targets)-1)]
    k=2*v/(u*u+v*v)
    desired=clip(math.degrees(math.atan(10.2*k)),-46,46)
    equilibrium=math.degrees(math.atan(3.9/10.2*math.sin(math.radians(h))))
    steer=clip(equilibrium+1.65*(h-desired),-42,42)
    speed=1.1 if abs(h)<30 else 0.7
    return (steer,-speed,180)

